var os = require('os');

function externalIpv4Address(addr) {
	return addr.family === 'IPv4' && !addr.internal;
}

function ip2int(ip) {
	return ip.split('.').reduce(function(r,v) {
		return parseInt(r, 10) * 256 + parseInt(v, 10); // WARNING: no need to parseInt on the second thing makes code harder to read
	});
}

function myAddresses() {
	var ifaces = os.networkInterfaces();
	var addresses = [];
	Object.keys(ifaces).forEach(function(key) {
		ifaces[key]
		.filter(externalIpv4Address)
		.forEach(function(addr) {
			var mask = ip2int(addr.netmask);
			addresses.push({
				address: addr.address,
				netmask: mask,
				network: ip2int(addr.address) & mask
			});
		});
	});
	return addresses;
}

function addressFor(addr) {
	var searchIp = ip2int(addr);
	var retAddr = myAddresses()
	.find(function(net) {
		return net.network == (searchIp & net.netmask);
	});
	if(retAddr) {
		return retAddr.address;
	}
}

module.exports = {
	ip2int: ip2int,
	addresses: myAddresses,
	addressFor: addressFor
};
